package seokhoon.trade.adapter.persistence;
import jakarta.persistence.*;import seokhoon.trade.domain.research.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="target_price_consensus_snapshots",uniqueConstraints=@UniqueConstraint(name="uk_target_price_consensus",columnNames={"stock_code","consensus_date","source"}))
public class TargetPriceConsensusSnapshotEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(name="stock_code",nullable=false,length=20)String stockCode;@Column(name="consensus_date",nullable=false)LocalDate consensusDate;@Column(name="target_price",nullable=false,precision=19,scale=4)BigDecimal targetPrice;@Column(name="current_price",precision=19,scale=4)BigDecimal currentPrice;@Column(name="upside_rate",precision=19,scale=4)BigDecimal upsideRate;@Column(name="analyst_count")Integer analystCount;@Enumerated(EnumType.STRING)@Column(name="source",nullable=false,length=20)ConsensusSource source;@Column(name="provider_name",length=100)String providerName;@Enumerated(EnumType.STRING)@Column(name="status",nullable=false,length=20)ConsensusStatus status;@Column(name="created_at",nullable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;protected TargetPriceConsensusSnapshotEntity(){}
 static TargetPriceConsensusSnapshotEntity from(TargetPriceConsensusSnapshot v){var e=new TargetPriceConsensusSnapshotEntity();e.id=v.id();e.update(v);return e;}void update(TargetPriceConsensusSnapshot v){stockCode=v.stockCode();consensusDate=v.consensusDate();targetPrice=v.targetPrice();currentPrice=v.currentPrice();upsideRate=v.upsideRate();analystCount=v.analystCount();source=v.source();providerName=v.providerName();status=v.status();createdAt=v.createdAt();updatedAt=v.updatedAt();}TargetPriceConsensusSnapshot toDomain(){return new TargetPriceConsensusSnapshot(id,stockCode,consensusDate,targetPrice,currentPrice,upsideRate,analystCount,source,providerName,status,createdAt,updatedAt);}
}
